const cinemaAbout=document.createElement('dialog');cinemaAbout.id='cinemaAbout';cinemaAbout.className='work-dialog';cinemaAbout.setAttribute('aria-labelledby','cinemaAboutName');cinemaAbout.style.cssText='width:min(580px,90vw);text-align:center;padding:32px';
cinemaAbout.innerHTML='<img src="assets/cinema-studio-icon.png" alt="Icono de Cinema Studio" style="width:112px;height:112px;object-fit:contain"><h2 id="cinemaAboutName" style="font-size:32px;line-height:1.15;margin:20px 0 4px">Cinema Studio</h2><p style="margin:0;color:var(--accent-2);display:flex;justify-content:center;align-items:center;gap:5px;font-size:12px">by <img src="assets/lqtac-wordmark.png" alt="LQTAC" style="width:64px;height:25px;object-fit:contain"></p><p id="cinemaAboutVersion"></p><p id="cinemaAboutDescription"></p><footer><button id="cinemaAboutManual" type="button">Manual de usuario</button><button id="cinemaAboutClose" type="button">Cerrar</button></footer>';document.body.append(cinemaAbout);
async function openCinemaAbout(){try{const info=await window.lqtacDesktop.appInfo();$('#cinemaAboutVersion').textContent='Versión '+info.version;$('#cinemaAboutDescription').textContent=info.description;cinemaAbout.showModal();}catch(error){toast(error.message);}}
$('#cinemaAboutClose').onclick=()=>cinemaAbout.close();$('#cinemaAboutManual').onclick=()=>window.lqtacDesktop.openUserManual().catch(error=>toast(error.message));
